"""Additional stdin/stdout problems for the shared problem bank."""


def _problem(title, slug, difficulty, description, cases):
    return {
        "title": title,
        "slug": slug,
        "difficulty": difficulty,
        "description": description,
        "test_cases": [
            {
                "input_data": input_data,
                "expected_output": output,
                "is_sample": is_sample,
            }
            for input_data, output, is_sample in cases
        ],
    }


